body.usercss:

div.multi_form_box{
    display:table;
    margin:0 auto;
}
div.form_area{
	display:inline-flex;
}
div.form_area .multi_form_box{
	margin:0 auto;
}

userscript.function:

        	$sObject._vp[0].parentElement.classList.add("sepoa_form_label_top");

            formObj = $sObject.formObj = new SepoaMultiDhtmlXFormObject(formBox, 'formObj', [
                [
                	{type:"block", width:"405",blockOffset: "0" ,list:[
                		{type: "select", width:"116", name: "project", label:Sepoa.cache.text.get("SAVE_POPUP.PROJECT"), options:formModuleOption},
                		{type: "newcolumn"},
                		{type: "file" , name: "PREVIEW", label:Sepoa.cache.text.get("SAVE_POPUP.PREVIEW")},
                		{type: "file" , name: "PREHOVER", label:Sepoa.cache.text.get("SAVE_POPUP.PREHOVER")}
                	]},
                    {type: "input", width:"400", value: "", label:Sepoa.cache.text.get("SAVE_POPUP.NAME"), name: "NAME", required:true},
                    {type: "input", width:"400", rows:5, value: "", label:Sepoa.cache.text.get("SAVE_POPUP.DESCRIPTION"), name: "DESCRIPTION", required:true},
                    {type: "input", name: "forceFlag", hidden:true},
                    {type: "input", name: "DATA", value:Sepoa.params.data, hidden:true},
                    {type: "input" , name: "PREVIEW_BASE64", hidden:true, required:true},
					{type: "input" , name: "PREHOVER_BASE64", hidden:true, required:true}                    
                ]
            ]);
            formObj.attachEvent("onChange", onChange);

            formObj.getInput('PREVIEW').setAttribute("accept", ".jpg,.jpeg,.png,.gif,.bmp");
            formObj.getInput('PREHOVER').setAttribute("accept", ".jpg,.jpeg,.png,.gif,.bmp");

            setSize();


	if(id == 'PREVIEW' || id == 'PREHOVER'){
		var inp = this.getInput(id);
		if(inp.files && inp.files[0]){
			var r = new FileReader();
			r.onload= function(e) {
        		formObj.setValue(id+"_BASE64", e.target.result);
    		};       		
    		r.readAsDataURL(inp.files[0]);	
		}
	}


            if(!formObj.validate()){
                return
            }

            formObj.setValue('forceFlag', force?"true":"false")
            doServiceAjax("sepoa.svc.tools.ScreenBuilder", "CONNECTION", "doSaveTemplate", null, function(so){
				switch(so.status){
				case "1":
					Alert(Sepoa.cache.text.get("MESSAGE.0003");
					selfObj.close();
					break;
				case "2":
					var that = this;
					Confirm(Sepoa.cache.text.get("MESSAGE.0004")+so.message, function(flag){
						if(flag){
							doSave(true);
						}
					})
					break;
				default:
					Alert(Sepoa.cache.text.get("MESSAGE.0005")+so.message);
					break;
				}
			});


var s = {width:400, height:350}

var tArray = [formObj];
for(var i in tArray){
    var t = tArray[i];
    if(t){
        var c = t._parent.children[0]
        var w = c.offsetWidth + 100;
        if(w > s.width) s.width = w;
    }
}

selfObj[selfObj.name].setDimension(s.width, s.height);
selfObj[selfObj.name].center();
